# textbook_coa_pds_algo.py
# Simple English point-by-point ChatGPT style tutorials for all 11 chapters of COA, PDS & ALGO

CHAPTERS_COA_PDS_ALGO = {('COA', 0): {'sub_id': 'COA', 'chap_idx': 0, 'title': 'Machine Instructions & Addressing Modes', 'real_life_examples': [{'title': 'Real-Life Analogy: The Treasure Map Coordinates', 'text': '• Immediate Addressing: Cash in your pocket ($20 bill right now).\n• Direct Addressing: Mailing a letter to a specific house address (e.g. 104 Main St).\n• Indirect Addressing: A bank locker key inside a drawer. You open the drawer (first address) to find the key that opens the real locker (second address)!'}], 'foundations': [{'number': '9.1', 'title': 'Effective Address (EA) in Common Addressing Modes', 'content': '• <b>What is Effective Address (EA)?</b> The actual physical address in main memory where the operand resides.<br/>• <b>Standard Addressing Modes Summary:</b><br/>&nbsp;&nbsp;1. <b>Immediate Mode:</b> Operand is part of the instruction itself. (Zero memory references!).<br/>&nbsp;&nbsp;2. <b>Direct (Absolute) Mode:</b> Address field contains EA: <b>EA = Address</b>. (1 memory reference).<br/>&nbsp;&nbsp;3. <b>Indirect Mode:</b> Address field contains pointer to EA: <b>EA = M[Address]</b>. (2 memory references).<br/>&nbsp;&nbsp;4. <b>Register Mode:</b> Operand resides in a CPU register R: <b>EA = R</b>. (Zero memory references, very fast).<br/>&nbsp;&nbsp;5. <b>Register Indirect Mode:</b> Register R contains memory address: <b>EA = [R]</b>. (1 memory reference).<br/>&nbsp;&nbsp;6. <b>PC-Relative Mode:</b> Used in branch jumps: <b>EA = PC + Offset</b>.<br/>&nbsp;&nbsp;7. <b>Indexed Mode:</b> Used in array traversal: <b>EA = Base Address + [Index Register]</b>.', 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: In PC-Relative mode, PC is already incremented to point to the NEXT instruction before computing EA = PC + Offset!'}, {'number': '9.2', 'title': 'Instruction Formats & Opcode Expansion', 'content': '• <b>Instruction Word Fields:</b> [ Opcode | Mode | Register Address | Memory Address ].<br/>• <b>Number of Addresses:</b><br/>&nbsp;&nbsp;- 3-Address: ADD R1, R2, R3 (R1 = R2 + R3).<br/>&nbsp;&nbsp;- 2-Address: ADD R1, R2 (R1 = R1 + R2).<br/>&nbsp;&nbsp;- 1-Address: ADD X (Accumulator AC = AC + M[X]).<br/>&nbsp;&nbsp;- 0-Address: ADD (Stack machine: pops top two operands, adds, pushes result).<br/>• <b>Expanding Opcode Technique:</b> Allows variable length opcodes to support many instructions with different address counts in a fixed word size.', 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: In an expanding opcode question, unused bit patterns from k-bit opcodes are multiplied by 2^(extra bits) to calculate how many shorter-address instructions can be created.'}, {'number': '9.3', 'title': 'RISC vs CISC Architecture Differences', 'content': '• <b>RISC (Reduced Instruction Set Computer):</b><br/>&nbsp;&nbsp;- Simple, single-cycle instructions with fixed instruction length.<br/>&nbsp;&nbsp;- <b>Load/Store Architecture:</b> Arithmetic operations only occur between registers.<br/>&nbsp;&nbsp;- Hardwired control unit, heavily pipelined, large register file.<br/>• <b>CISC (Complex Instruction Set Computer):</b><br/>&nbsp;&nbsp;- Complex, multi-cycle instructions with variable instruction length.<br/>&nbsp;&nbsp;- Memory-to-memory operations allowed (e.g. ADD directly to memory).<br/>&nbsp;&nbsp;- Microprogrammed control unit with fewer general registers.', 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: In RISC processors, ALU instructions CANNOT access memory directly! Data must be explicitly loaded into registers using LOAD/STORE instructions.'}], 'worked_examples': [{'title': 'Worked Example: Memory References for Different Modes', 'problem': 'An instruction is stored at memory location 1000. It has opcode, mode, and address field 500. Memory at 500 contains 800, and memory at 800 contains 25. How many memory references are required to fetch and execute the instruction in Indirect Addressing Mode?', 'steps': ['Step 1: Instruction fetch requires 1 memory reference (read address 1000).', 'Step 2: Read address field 500 from memory to find effective address pointer: reads 800 (1 memory reference).', 'Step 3: Read effective address 800 from memory to fetch operand 25 (1 memory reference).', 'Step 4: Total memory references = 1 (fetch) + 2 (operand fetch) = 3 references.'], 'answer': 'Total memory references = 3 (1 for instruction fetch + 2 for operand fetch).'}], 'exam_traps': ['Do not forget the 1 memory reference needed to FETCH the instruction itself!', 'Immediate addressing requires 1 memory reference for instruction fetch, but 0 references for operand fetch.']}, ('COA', 1): {'sub_id': 'COA', 'chap_idx': 1, 'title': 'ALU, Control Unit & Memory Interfacing', 'real_life_examples': [{'title': 'Real-Life Analogy: The Speed Multiplication Trick & Direct Flight DMA', 'text': "• Booth's Algorithm: Like converting 99 × 7 into (100 - 1) × 7 = 700 - 7 = 693. Instead of adding 99 times, you subtract once and add once!\n• DMA (Direct Memory Access): Like a freight train delivering cargo straight to the warehouse (RAM) without asking the airport CEO (CPU) to inspect each individual parcel."}], 'foundations': [{'number': '10.1', 'title': "Booth's Multiplication Rules (Q_i, Q_{i-1})", 'content': "• Booth's Algorithm multiplies signed 2's complement numbers efficiently.<br/>• <b>Look at two bits (Q_0, Q_{-1}):</b><br/>&nbsp;&nbsp;• <b>00:</b> Do nothing (only arithmetic shift right A, Q, Q_{-1}).<br/>&nbsp;&nbsp;• <b>01:</b> End of a string of 1s ⇒ <b>Add Multiplicand (A = A + M)</b>, then shift right.<br/>&nbsp;&nbsp;• <b>10:</b> Beginning of a string of 1s ⇒ <b>Subtract Multiplicand (A = A - M)</b>, then shift right.<br/>&nbsp;&nbsp;• <b>11:</b> Do nothing (only arithmetic shift right).<br/>• <b>Best Case:</b> Alternating 0s or all 1s/all 0s (minimum additions/subtractions).<br/>• <b>Worst Case:</b> Isolated 1s (e.g. 01010101): requires n additions/subtractions.", 'crucial_rule': "🎯 GOLDEN RULE FOR GATE: In Booth's algorithm, the shift operation is always an ARITHMETIC SHIFT RIGHT (ASR), which preserves the sign bit (MSB is replicated)!"}, {'number': '10.2', 'title': 'Hardwired vs Microprogrammed Control Unit', 'content': '• <b>Hardwired Control Unit:</b><br/>&nbsp;&nbsp;- Implemented using combinational logic gates, decoders, and flip-flops.<br/>&nbsp;&nbsp;- <b>Extremely fast execution</b>, but inflexible (cannot modify instructions without redesigning hardware). Used in RISC.<br/>• <b>Microprogrammed Control Unit:</b><br/>&nbsp;&nbsp;- Control signals generated by reading micro-instructions from Control Memory (ROM).<br/>&nbsp;&nbsp;- Flexible and easy to update, but slower due to memory access time. Used in CISC.<br/>• <b>Horizontal vs Vertical Microprogramming:</b><br/>&nbsp;&nbsp;- <b>Horizontal:</b> 1 bit per control signal (no decoding, very wide, very fast).<br/>&nbsp;&nbsp;- <b>Vertical:</b> Control signals encoded into groups (narrower, requires decoders, slower).', 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: If a control unit has k mutually exclusive control signals, Horizontal needs k bits, whereas Vertical needs only ⌈log2(k + 1)⌉ bits!'}, {'number': '10.3', 'title': 'DMA (Direct Memory Access) & Cycle Stealing', 'content': '• <b>What is DMA?</b> Allows high-speed I/O devices (disk, network) to transfer blocks of data directly to/from memory without CPU intervention.<br/>• <b>Transfer Modes:</b><br/>&nbsp;&nbsp;1. <b>Burst Mode:</b> DMA holds bus until entire block is transferred. CPU is paused.<br/>&nbsp;&nbsp;2. <b>Cycle Stealing Mode:</b> DMA transfers 1 word per bus cycle, stealing cycles when CPU does not need system bus.<br/>• <b>CPU Paused Percentage in Cycle Stealing:</b><br/>&nbsp;&nbsp;<b>% CPU Slowdown = (DMA Time per second / Total Time) × 100%</b>.<br/>&nbsp;&nbsp;= (Device Data Rate / Bus Bandwidth) × 100%.', 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: In Cycle Stealing: Percentage of CPU time consumed = (Data preparation time per byte / Bus cycle time)^(-1) = (Device transfer rate / Bus bandwidth) × 100%.'}], 'worked_examples': [{'title': 'Worked Example: DMA Cycle Stealing Percentage', 'problem': 'A hard disk transfers data at 2 MB/sec. The system bus has a transfer speed of 10 MB/sec. What percentage of CPU cycle time is stolen by the DMA controller during transfer?', 'steps': ['Step 1: Identify Device transfer rate = 2 MB/sec.', 'Step 2: Identify Bus bandwidth = 10 MB/sec.', 'Step 3: Formula: CPU Time Stolen = (Device Rate / Bus Rate) × 100%.', 'Step 4: Compute: (2 MB/s / 10 MB/s) × 100% = 0.2 × 100% = 20%.'], 'answer': 'CPU cycle time stolen = 20%.'}], 'exam_traps': ['Do not confuse horizontal microprogramming (unencoded, 1 bit per signal) with vertical (encoded into log2 bits)!', 'In DMA questions, verify units: bytes/sec vs words/sec and bits vs bytes.']}, ('COA', 2): {'sub_id': 'COA', 'chap_idx': 2, 'title': 'Memory Hierarchy, Cache Mapping & AMAT', 'real_life_examples': [{'title': 'Real-Life Analogy: The Desk, Bookshelf & City Library', 'text': "• Memory Hierarchy: CPU Registers are the textbook open on your desk right now (instant access). Cache is the shelf within arm's reach (few seconds). RAM is the university library across the street (minutes). Hard disk is ordering a book from another country (days)!"}], 'foundations': [{'number': '11.1', 'title': 'Cache Address Splitting in Mapping Techniques', 'content': '• A main memory physical address is partitioned into 3 fields:<br/>&nbsp;&nbsp;1. <b>Direct Mapped Cache:</b><br/>&nbsp;&nbsp;&nbsp;&nbsp;- [ Tag Bits | Line / Block Bits | Word / Byte Offset ]<br/>&nbsp;&nbsp;&nbsp;&nbsp;- Word Offset = <b>log2(Block Size in bytes)</b>.<br/>&nbsp;&nbsp;&nbsp;&nbsp;- Line Bits = <b>log2(Number of Cache Lines)</b>.<br/>&nbsp;&nbsp;&nbsp;&nbsp;- Tag Bits = Address Bits - Line Bits - Word Offset.<br/>&nbsp;&nbsp;2. <b>k-Way Set-Associative Cache:</b><br/>&nbsp;&nbsp;&nbsp;&nbsp;- [ Tag Bits | Set Bits | Word / Byte Offset ]<br/>&nbsp;&nbsp;&nbsp;&nbsp;- Number of Sets = <b>(Total Cache Lines) / k</b>.<br/>&nbsp;&nbsp;&nbsp;&nbsp;- Set Bits = <b>log2(Number of Sets)</b>.<br/>&nbsp;&nbsp;3. <b>Fully Associative Cache:</b><br/>&nbsp;&nbsp;&nbsp;&nbsp;- [ Tag Bits | Word / Byte Offset ] (Zero set/line bits! A block can go anywhere).', 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: In k-way set-associative cache: Number of Sets = Total Cache Size / (k × Block Size). Tag Directory Size = (Number of Lines) × (Tag Bits + Valid Bit + Dirty Bit)!'}, {'number': '11.2', 'title': 'Average Memory Access Time (AMAT)', 'content': '• <b>Hierarchical Organization (CPU checks L1 first; on miss, visits L2/Memory):</b><br/>&nbsp;&nbsp;<b>AMAT = t_{hit_L1} + (Miss_Rate_L1 × Miss_Penalty_L1)</b>.<br/>&nbsp;&nbsp;If L2 is present: Miss_Penalty_L1 = t_{hit_L2} + (Miss_Rate_L2 × t_{memory}).<br/>• <b>Simultaneous Access (CPU searches L1 and Main Memory in parallel):</b><br/>&nbsp;&nbsp;<b>AMAT = (Hit_Rate × t_{cache}) + (Miss_Rate × t_{memory})</b>.<br/>• <b>Write Policies:</b><br/>&nbsp;&nbsp;- <b>Write-Through:</b> Updates both cache and memory immediately (slow, needs write buffer).<br/>&nbsp;&nbsp;- <b>Write-Back:</b> Updates only cache; updates memory only when dirty block is evicted (faster, needs Dirty Bit).', 'crucial_rule': "🎯 GOLDEN RULE FOR GATE: Unless the question explicitly specifies 'simultaneous access', ALWAYS use the Hierarchical formula where Miss Penalty includes access to the lower level!"}, {'number': '11.3', 'title': 'The 3 Cs of Cache Misses', 'content': '• <b>1. Compulsory (Cold) Miss:</b> First-ever access to a memory block. Unavoidable unless prefetching is used.<br/>• <b>2. Capacity Miss:</b> Cache is completely full and cannot hold all working-set blocks. Solved by increasing cache size.<br/>• <b>3. Conflict Miss:</b> Multiple blocks map to the same set/line even though other sets are empty. Occurs in Direct-Mapped and Set-Associative caches.<br/>• <b>Zero Conflict Misses:</b> Fully Associative cache has ZERO conflict misses!', 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: Fully Associative caches eliminate Conflict misses completely! They only suffer from Compulsory and Capacity misses.'}], 'worked_examples': [{'title': 'Worked Example: Calculating Tag, Set, and Offset Bits', 'problem': 'A 32-bit byte-addressable system has a 64 KB 4-way set-associative cache with 32-byte blocks. Find the number of Tag, Set, and Word Offset bits.', 'steps': ['Step 1: Word Offset = log2(Block Size) = log2(32 bytes) = 5 bits.', 'Step 2: Total number of cache lines = Cache Size / Block Size = 64 KB / 32 B = 65536 / 32 = 2048 lines.', 'Step 3: Number of sets = Total Lines / k = 2048 / 4 = 512 sets.', 'Step 4: Set bits = log2(512) = 9 bits.', 'Step 5: Tag bits = 32 - (Set bits + Offset bits) = 32 - (9 + 5) = 32 - 14 = 18 bits.'], 'answer': 'Tag = 18 bits, Set = 9 bits, Word Offset = 5 bits.'}], 'exam_traps': ['Watch out for byte-addressable vs word-addressable systems! If word size is 4 bytes, offset uses word count instead of byte count.', 'Total cache size is data size only; tag directory overhead is NOT counted unless specifically requested.']}, ('COA', 3): {'sub_id': 'COA', 'chap_idx': 3, 'title': 'Pipeline Hazards, Speedup & Instruction Level Parallelism', 'real_life_examples': [{'title': 'Real-Life Analogy: The Laundromat Assembly Line', 'text': '• Laundry Pipelining: Person 1 washes, Person 2 dries, Person 3 folds, Person 4 stores. Instead of waiting 2 hours per load, a new load completes every 30 minutes! Pipelining increases throughput (instructions per second), NOT the latency of a single instruction.'}], 'foundations': [{'number': '12.1', 'title': 'The Three Classic Pipeline Hazards', 'content': '• <b>1. Structural Hazard (Resource Conflict):</b> Hardware cannot support all concurrent instructions (e.g. single memory port accessed by IF and MEM simultaneously). Solved by separate Instruction and Data caches (Harvard Architecture).<br/>• <b>2. Data Hazard (Dependencies between instructions):</b><br/>&nbsp;&nbsp;• <b>RAW (Read After Write - True Dependency):</b> Instruction tries to read a register before prior instruction writes to it. Solved by <b>Operand Forwarding (Bypassing)</b> or compiler stalls.<br/>&nbsp;&nbsp;• <b>WAR (Write After Read - Anti-dependency):</b> Cannot happen in classic in-order RISC pipeline.<br/>&nbsp;&nbsp;• <b>WAW (Write After Write - Output dependency):</b> Cannot happen in in-order pipelines.<br/>• <b>3. Control Hazard (Branch Instruction):</b> Pipeline fetches wrong instructions before branch condition and target address are resolved. Solved by Branch Prediction, Delayed Branching, or target buffers.', 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: In a standard 5-stage in-order RISC pipeline (IF, ID, EX, MEM, WB), only RAW hazards cause data stalls! WAR and WAW hazards only occur in out-of-order execution processors.'}, {'number': '12.2', 'title': 'Pipeline Clock Period, Speedup & CPI', 'content': '• <b>Pipeline Clock Cycle (τ):</b> Set by the slowest stage plus register delay:<br/>&nbsp;&nbsp;<b>τ = max(stage delays) + d</b>.<br/>• <b>Time to execute n instructions in a k-stage pipeline:</b><br/>&nbsp;&nbsp;<b>T_pipe = [ k + (n - 1) + Stalls ] × τ</b>.<br/>• <b>Speedup (S) of Pipeline over Non-pipelined:</b><br/>&nbsp;&nbsp;<b>S = T_{non-pipe} / T_{pipe} = (n × k × τ) / [ (k + n - 1) × τ ]</b>.<br/>&nbsp;&nbsp;For large n (n → ∞) and ideal CPI = 1: <b>Maximum Speedup = k</b> (number of stages!).', 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: Ideal CPI of an un-stalled pipeline is 1. If branch stalls or data hazards occur: Effective CPI = 1 + (Stall cycles per instruction). Actual Speedup = k / Effective CPI!'}], 'worked_examples': [{'title': 'Worked Example: Pipeline Speedup with Hazards', 'problem': 'A 5-stage pipeline has stage delays of 150 ps, 120 ps, 180 ps, 160 ps, 140 ps with a pipeline register delay of 20 ps. In a non-pipelined implementation, total execution time per instruction is 750 ps. Calculate the clock period and maximum speedup for a large number of instructions.', 'steps': ['Step 1: Clock period τ = max(stage delays) + register delay = 180 ps + 20 ps = 200 ps.', 'Step 2: Non-pipelined time per instruction = 750 ps.', 'Step 3: Ideal pipelined time per instruction (n → ∞) = 1 instruction per clock cycle = 200 ps.', 'Step 4: Speedup S = 750 ps / 200 ps = 3.75.'], 'answer': 'Clock period = 200 ps; Speedup = 3.75.'}], 'exam_traps': ['Do not forget to add the pipeline register delay to the maximum stage delay!', 'Speedup is k only when all stages are perfectly balanced and register delay is zero.']}, ('PDS', 0): {'sub_id': 'PDS', 'chap_idx': 0, 'title': 'Programming in C & Recursion Tracing', 'real_life_examples': [{'title': 'Real-Life Analogy: The Russian Matryoshka Doll (Recursion)', 'text': '• Recursion: Opening a Russian nesting doll to find a smaller doll inside. You keep unpacking until you hit the smallest solid doll (Base Case). Then you pack them all back together (Call Stack unwinding)!\n• Array Decay: Handing someone a business card with your home address instead of shipping your entire house to them.'}], 'foundations': [{'number': '13.1', 'title': 'Pointers & Array Equivalence in C', 'content': '• <b>What is an array name?</b> In C, an array name <code>arr</code> is a pointer to its first element: <code>arr == &arr[0]</code>.<br/>• <b>Subscript Rule:</b> <code>arr[i] == *(arr + i) == *(i + arr) == i[arr]</code>.<br/>&nbsp;&nbsp;- In C, <code>3[arr]</code> is completely valid and equals <code>arr[3]</code>!<br/>• <b>Pointer Increment Nuances:</b><br/>&nbsp;&nbsp;• <code>*p++</code>: Read <code>*p</code> first, then increment pointer <code>p</code> to next memory slot.<br/>&nbsp;&nbsp;• <code>(*p)++</code>: Read value, increment the integer value inside memory by 1; pointer stays at same spot.<br/>&nbsp;&nbsp;• <code>*++p</code>: Increment pointer <code>p</code> first, then dereference.', 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: When an array is passed to a function, it decays to a simple pointer! Inside the function, sizeof(arr) gives the size of a pointer (4 or 8 bytes), NOT the full array size!'}, {'number': '13.2', 'title': 'Short-Circuit Evaluation in C', 'content': '• <b>Logical AND (expr1 && expr2):</b><br/>&nbsp;&nbsp;- If expr1 evaluates to <b>0 (False)</b>, expr2 is <b>NEVER EXECUTED</b>!<br/>&nbsp;&nbsp;- Any side-effects (like <code>x++</code> or function calls) inside expr2 are completely skipped.<br/>• <b>Logical OR (expr1 || expr2):</b><br/>&nbsp;&nbsp;- If expr1 evaluates to <b>non-zero (True)</b>, expr2 is <b>NEVER EXECUTED</b>!<br/>• <b>Precedence:</b> Logical AND (&&) has higher precedence than Logical OR (||).', 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: In expression (a++ || b++): if a starts non-zero (True), b++ is NEVER evaluated, and b remains completely unchanged!'}, {'number': '13.3', 'title': 'Storage Classes & Scope in C', 'content': '• <b>auto:</b> Default for local variables. Stored in Stack; scope is block-local; lifetime is function call.<br/>• <b>register:</b> Request to store in CPU register for speed. Cannot take its address with <code>&var</code>!<br/>• <b>static:</b> Stored in Data Segment (BSS/Data). Retains its value across multiple function calls; initialized only once to 0.<br/>• <b>extern:</b> Declares a global variable defined in another file/scope without allocating new memory.', 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: Static local variables are initialized ONLY ONCE when the program starts. On subsequent calls to the function, the initialization line is completely ignored!'}], 'worked_examples': [{'title': 'Worked Example: Tracing Pointer Expressions in C', 'problem': "Given int a[] = {10, 20, 30, 40, 50}; int *p = a; What is the output of printf('%d %d', *p++, (*p)++); followed by printf('%d', *p); ?", 'steps': ['Step 1: Pointer p points to a[0] (value 10).', "Step 2: Note that in C, argument evaluation order in printf is unspecified, but let's trace step by step sequentially:", 'Step 3: *p++ fetches 10, then advances p to point to a[1] (20).', 'Step 4: (*p)++ increments the value at a[1] from 20 to 21, but expression evaluates to 20.', 'Step 5: Afterwards, a[1] is now 21, and *p points to a[1] with value 21.'], 'answer': 'a[1] becomes 21; value pointed to by p is 21.'}], 'exam_traps': ["sizeof('a') in C is sizeof(int) = 4 bytes! In C++, sizeof('a') is 1 byte.", 'Array out-of-bounds access in C produces Undefined Behavior, not a compilation error or runtime crash!']}, ('PDS', 1): {'sub_id': 'PDS', 'chap_idx': 1, 'title': 'Linear Data Structures - Stacks, Queues & Linked Lists', 'real_life_examples': [{'title': 'Real-Life Analogy: Browser Back Button & Cafeteria Line', 'text': "• Stack (LIFO): The 'Back' button in your web browser. The last page you visited is the first page that pops back up.\n• Queue (FIFO): Standing in line at a cinema ticket counter. First person in line gets the ticket first."}], 'foundations': [{'number': '14.1', 'title': 'Infix, Postfix & Stack Conversions', 'content': '• <b>Postfix Evaluation using Stack:</b><br/>&nbsp;&nbsp;1. Scan expression from left to right.<br/>&nbsp;&nbsp;2. If operand (number), push onto stack.<br/>&nbsp;&nbsp;3. If operator: pop two operands (op2 = pop(), op1 = pop()).<br/>&nbsp;&nbsp;4. Compute: <b>result = op1 (operator) op2</b>. Push result back onto stack.<br/>• <b>Stack Permutations:</b> Number of valid stack permutations of n elements = <b>Catalan Number C_n = (1 / (n + 1)) × C(2n, n)</b>.<br/>&nbsp;&nbsp;- Values: C_1 = 1, C_2 = 2, C_3 = 5, C_4 = 14, C_5 = 42.', 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: In postfix evaluation, when an operator arrives: the first popped item is the RIGHT operand (op2), and the second popped item is the LEFT operand (op1): result = op1 op op2!'}, {'number': '14.2', 'title': 'Circular Queue Boundary Conditions', 'content': '• Using an array of size <b>N</b> with front and rear pointers:<br/>&nbsp;&nbsp;• <b>Enqueue:</b> <code>rear = (rear + 1) % N; queue[rear] = item;</code><br/>&nbsp;&nbsp;• <b>Dequeue:</b> <code>front = (front + 1) % N; item = queue[front];</code><br/>• <b>Full Condition (leaving 1 empty slot):</b> <b>(rear + 1) % N == front</b>.<br/>• <b>Empty Condition:</b> <b>front == rear</b>.<br/>• <b>Number of elements currently in Queue:</b> <b>(rear - front + N) % N</b>.', 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: In a circular queue of array size N, leaving one empty slot allows max capacity of (N - 1) elements to distinguish Full from Empty!'}, {'number': '14.3', 'title': "Linked Lists & Floyd's Cycle Detection", 'content': "• <b>Floyd's Tortoise and Hare Algorithm:</b><br/>&nbsp;&nbsp;- Slow pointer moves 1 step; Fast pointer moves 2 steps.<br/>&nbsp;&nbsp;- If they meet, a <b>cycle exists</b> in the linked list!<br/>&nbsp;&nbsp;- <b>Finding Start of Cycle:</b> Reset slow to Head. Keep fast at meeting point. Move both 1 step at a time. The node where they meet is the exact cycle entry node!<br/>• <b>Reversing a Singly Linked List:</b> Done in O(N) time and O(1) auxiliary space using 3 pointers (prev, curr, next).", 'crucial_rule': "🎯 GOLDEN RULE FOR GATE: Floyd's cycle detection runs in O(N) time with O(1) extra space! The distance from Head to cycle-start equals distance from meeting-point to cycle-start."}], 'worked_examples': [{'title': 'Worked Example: Evaluating Postfix Expression', 'problem': 'Evaluate the postfix expression: 6 2 3 + * 3 8 2 / + * 2 ^ 3 +', 'steps': ['Step 1: Push 6, push 2, push 3. Stack: [6, 2, 3].', "Step 2: '+' arrives: pop 3 and 2. Compute 2 + 3 = 5. Push 5. Stack: [6, 5].", "Step 3: '*' arrives: pop 5 and 6. Compute 6 * 5 = 30. Push 30. Stack: [30].", 'Step 4: Push 3, push 8, push 2. Stack: [30, 3, 8, 2].', "Step 5: '/' arrives: pop 2 and 8. Compute 8 / 2 = 4. Push 4. Stack: [30, 3, 4].", "Step 6: '+' arrives: pop 4 and 3. Compute 3 + 4 = 7. Push 7. Stack: [30, 7].", "Step 7: '*' arrives: pop 7 and 30. Compute 30 * 7 = 210. Push 210. Stack: [210]."], 'answer': 'Evaluated result = 210 (before remaining operations).'}], 'exam_traps': ['In postfix to infix, parentheses must be preserved when operator precedence demands it!', 'Double-ended queue (Deque) can implement both a Stack and a Queue in O(1) time per operation.']}, ('PDS', 2): {'sub_id': 'PDS', 'chap_idx': 2, 'title': 'Trees, Binary Search Trees & Binary Heaps', 'real_life_examples': [{'title': 'Real-Life Analogy: The Corporate Hierarchy & Hospital Emergency Triage', 'text': '• Binary Tree: Like a CEO who has at most 2 direct Vice Presidents, each VP having at most 2 directors.\n• Heap (Priority Queue): Like an emergency room triage where patients are treated by severity of injury (highest priority first), regardless of arrival time!'}], 'foundations': [{'number': '15.1', 'title': 'Binary Tree Fundamental Properties', 'content': '• <b>Key Formulas for Binary Trees:</b><br/>&nbsp;&nbsp;1. <b>Leaf vs Degree-2 Nodes:</b> In any binary tree: <b>n_0 = n_2 + 1</b> (Number of leaf nodes = Number of degree-2 nodes + 1).<br/>&nbsp;&nbsp;2. <b>Max nodes at height h (root at h=0):</b> <b>2^(h + 1) - 1</b>.<br/>&nbsp;&nbsp;3. <b>Min height for n nodes:</b> <b>⌈log2(n + 1)⌉ - 1</b>.<br/>• <b>Unique Tree Reconstruction:</b><br/>&nbsp;&nbsp;- Inorder + Preorder gives a UNIQUE binary tree.<br/>&nbsp;&nbsp;- Inorder + Postorder gives a UNIQUE binary tree.<br/>&nbsp;&nbsp;- Preorder + Postorder does NOT give a unique tree (unless strictly full binary tree)!', 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: Inorder traversal MUST be given to uniquely reconstruct a binary tree! Preorder + Postorder is NEVER sufficient for general binary trees.'}, {'number': '15.2', 'title': 'Binary Search Trees (BST) & AVL Trees', 'content': '• <b>BST Inorder Traversal:</b> Inorder traversal of any BST always produces strictly ASCENDING sorted order.<br/>• <b>Number of distinct BSTs with n distinct keys:</b> <b>Catalan Number C_n</b>.<br/>• <b>AVL Trees (Height-Balanced BST):</b><br/>&nbsp;&nbsp;- Balance Factor = <b>Height(Left Subtree) - Height(Right Subtree) ∈ {-1, 0, +1}</b>.<br/>&nbsp;&nbsp;- 4 Rebalancing Rotations: LL, RR (single rotations) and LR, RL (double rotations).<br/>&nbsp;&nbsp;- Minimum nodes in AVL of height h: <b>N(h) = N(h - 1) + N(h - 2) + 1</b> (with N(0)=1, N(1)=2).', 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: In any BST, the node with maximum value has NO right child, and the node with minimum value has NO left child!'}, {'number': '15.3', 'title': 'Binary Heap Array Representation & Complexities', 'content': '• In a 1-based index array representation for a node at index <b>i</b>:<br/>&nbsp;&nbsp;• Parent index: <b>⌊i / 2⌋</b>.<br/>&nbsp;&nbsp;• Left child index: <b>2i</b>.<br/>&nbsp;&nbsp;• Right child index: <b>2i + 1</b>.<br/>• <b>Heap Operations Time Complexity:</b><br/>&nbsp;&nbsp;- Find Min/Max: <b>O(1)</b>.<br/>&nbsp;&nbsp;- Insert: <b>O(log n)</b>.<br/>&nbsp;&nbsp;- Delete Min/Max: <b>O(log n)</b>.<br/>&nbsp;&nbsp;- <b>Build-Heap (from arbitrary array):</b> <b>O(n)</b> time (NOT O(n log n)! Tested repeatedly in GATE!).', 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: Building a heap of n elements takes O(n) time, NOT O(n log n)! Sum of heights ∑ (h / 2^h) converges to 2, proving linear time.'}], 'worked_examples': [{'title': 'Worked Example: Reconstructing Tree from Preorder & Inorder', 'problem': 'Given Preorder: [A, B, D, E, C, F] and Inorder: [D, B, E, A, F, C]. Find the Postorder traversal.', 'steps': ['Step 1: First element in Preorder is Root = A.', 'Step 2: Locate A in Inorder: Left subtree is {D, B, E}, Right subtree is {F, C}.', 'Step 3: In Preorder, next 3 elements {B, D, E} belong to Left subtree. Root of Left subtree is B.', 'Step 4: Locate B in Inorder: D is Left child of B, E is Right child of B.', 'Step 5: For Right subtree: Preorder has C first ⇒ C is root; Inorder has F before C ⇒ F is Left child of C.', 'Step 6: Compute Postorder (Left, Right, Root): D, E, B, F, C, A.'], 'answer': 'Postorder: D, E, B, F, C, A.'}], 'exam_traps': ['In a Min-Heap, the maximum element is always at one of the leaf nodes (indices ⌊n/2⌋ + 1 to n)!', 'Deleting an arbitrary node from a heap takes O(log n) time, provided its index is known.']}, ('ALGO', 0): {'sub_id': 'ALGO', 'chap_idx': 0, 'title': 'Asymptotic Analysis, Master Theorem & Recurrences', 'real_life_examples': [{'title': 'Real-Life Analogy: The Speed of Transport Modes', 'text': "• Big-O: An upper bound promise. Like saying 'a flight from Delhi to Mumbai takes at most 3 hours'. It might take 2 hours, but will never exceed 3 hours in the worst case.\n• Master Theorem: A standard cookbook recipe for dividing a giant task into smaller sub-tasks."}], 'foundations': [{'number': '16.1', 'title': 'Big-O, Big-Omega & Big-Theta Explained', 'content': '• <b>Big-O (O):</b> Upper Bound: f(n) ≤ c · g(n) for all n ≥ n_0.<br/>• <b>Big-Omega (Ω):</b> Lower Bound: f(n) ≥ c · g(n) for all n ≥ n_0.<br/>• <b>Big-Theta (Θ):</b> Tight Bound: c1·g(n) ≤ f(n) ≤ c2·g(n). True if and only if both O and Ω hold!<br/>• <b>Standard Rate of Growth Hierarchy:</b><br/>&nbsp;&nbsp;<b>c &lt; log(log n) &lt; log n &lt; √n &lt; n &lt; n log n &lt; n² &lt; n³ &lt; 2^n &lt; n! &lt; n^n</b>.', 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: f(n) = Θ(g(n)) IF AND ONLY IF f(n) = O(g(n)) AND f(n) = Ω(g(n)). If one fails, Θ cannot hold!'}, {'number': '16.2', 'title': 'Master Theorem for Divide and Conquer', 'content': '• For recurrence: <b>T(n) = a · T(n / b) + Θ(n^k · log^p n)</b> (with a ≥ 1, b > 1):<br/>&nbsp;&nbsp;Compare <b>a</b> with <b>b^k</b>:<br/>&nbsp;&nbsp;1. <b>Case 1 (a > b^k):</b> <b>T(n) = Θ(n^(log_b a))</b>.<br/>&nbsp;&nbsp;2. <b>Case 2 (a = b^k):</b><br/>&nbsp;&nbsp;&nbsp;&nbsp;• If p > -1: <b>T(n) = Θ(n^k · log^{p+1} n)</b>.<br/>&nbsp;&nbsp;&nbsp;&nbsp;• If p = -1: T(n) = Θ(n^k · log(log n)).<br/>&nbsp;&nbsp;3. <b>Case 3 (a < b^k):</b> <b>T(n) = Θ(n^k · log^p n)</b>.', 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: Master theorem CANNOT be applied if: (1) a is not constant (e.g. 2^n T(n/2)), (2) b is not constant, or (3) f(n) is not a polynomial (e.g. T(n) = 2T(n/2) + n!).'}], 'worked_examples': [{'title': 'Worked Example: Solving Recurrence with Master Theorem', 'problem': 'Solve the recurrence relation T(n) = 4 T(n / 2) + n².', 'steps': ['Step 1: Identify parameters: a = 4, b = 2, f(n) = n² ⇒ k = 2, p = 0.', 'Step 2: Calculate b^k = 2² = 4.', 'Step 3: Compare a with b^k: a = 4 and b^k = 4 ⇒ a == b^k (Case 2).', 'Step 4: Since p = 0 > -1, formula gives T(n) = Θ(n^k · log^{p+1} n) = Θ(n² · log n).'], 'answer': 'T(n) = Θ(n² log n).'}], 'exam_traps': ['In T(n) = 2 T(n/2) + n/log n: Master Theorem fails because f(n) is not polynomially larger/smaller!', 'Master theorem for subtracting recurrences: T(n) = T(n - 1) + n gives Θ(n²).']}, ('ALGO', 1): {'sub_id': 'ALGO', 'chap_idx': 1, 'title': 'Sorting Algorithms, Lower Bounds & Hash Tables', 'real_life_examples': [{'title': 'Real-Life Analogy: Organizing Playing Cards & Coat Check Tickets', 'text': '• Insertion Sort: Like sorting playing cards in your hand—you pick each new card and slide it into its correct position among already sorted cards.\n• Hash Table: Like a coat checkroom with 100 hooks. You get a numbered ticket that instantly maps to your exact hook without searching the whole room.'}], 'foundations': [{'number': '17.1', 'title': 'Master Summary of Sorting Algorithms', 'content': '• <b>Comparison Table for GATE:</b><br/>&nbsp;&nbsp;• <b>Insertion Sort:</b> Best: O(n), Avg: O(n²), Worst: O(n²), Space: O(1), <b>Stable</b>.<br/>&nbsp;&nbsp;• <b>Merge Sort:</b> Best: O(n log n), Avg: O(n log n), Worst: O(n log n), Space: O(n), <b>Stable</b>.<br/>&nbsp;&nbsp;• <b>Heap Sort:</b> Best: O(n log n), Avg: O(n log n), Worst: O(n log n), Space: O(1), <b>NOT Stable</b>.<br/>&nbsp;&nbsp;• <b>Quick Sort:</b> Best: O(n log n), Avg: O(n log n), Worst: O(n²), Space: O(log n), <b>NOT Stable</b>.<br/>&nbsp;&nbsp;• <b>Counting Sort:</b> O(n + k) time and O(k) space (non-comparison, Stable).', 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: Merge Sort and Insertion Sort are STABLE! Quick Sort and Heap Sort are UNSTABLE! The theoretical lower bound for any comparison-based sort is Ω(n log n).'}, {'number': '17.2', 'title': 'Hash Table Collisions: Chaining vs Open Addressing', 'content': "• <b>Separate Chaining:</b> Each slot points to a linked list. Load factor α can exceed 1.<br/>• <b>Open Addressing:</b> All elements stored inside the hash table array. Load factor α ≤ 1.<br/>&nbsp;&nbsp;1. <b>Linear Probing:</b> <code>h(k, i) = (h'(k) + i) % m</code>. Suffers from <b>Primary Clustering</b>.<br/>&nbsp;&nbsp;2. <b>Quadratic Probing:</b> <code>h(k, i) = (h'(k) + c1·i + c2·i²) % m</code>. Suffers from <b>Secondary Clustering</b>.<br/>&nbsp;&nbsp;3. <b>Double Hashing:</b> <code>h(k, i) = (h1(k) + i · h2(k)) % m</code>. Eliminates clustering (h2(k) must be coprime to m).", 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: In open addressing, successful search takes O((1/α) ln(1/(1-α))) and unsuccessful search takes O(1 / (1 - α)) expected probes!'}], 'worked_examples': [{'title': 'Worked Example: Linear Probing Hash Collisions', 'problem': 'Insert keys [12, 22, 32, 42] into a hash table of size 10 using hash function h(k) = k % 10 with Linear Probing.', 'steps': ['Step 1: 12 % 10 = 2 ⇒ Slot 2 is empty. Store 12 at index 2.', 'Step 2: 22 % 10 = 2 ⇒ Collision! Probe (2 + 1) % 10 = 3. Slot 3 is empty. Store 22 at index 3.', 'Step 3: 32 % 10 = 2 ⇒ Collision at 2, collision at 3! Probe (2 + 2) % 10 = 4. Slot 4 is empty. Store 32 at index 4.', 'Step 4: 42 % 10 = 2 ⇒ Collisions at 2, 3, 4! Probe (2 + 3) % 10 = 5. Slot 5 is empty. Store 42 at index 5.'], 'answer': 'Final positions: 12 at 2, 22 at 3, 32 at 4, 42 at 5.'}], 'exam_traps': ['In QuickSort, picking the first or last element as pivot on an ALREADY SORTED array results in WORST-CASE O(n²) time!', 'Randomized QuickSort avoids worst-case for sorted inputs with high probability, but theoretical worst case is still O(n²).']}, ('ALGO', 2): {'sub_id': 'ALGO', 'chap_idx': 2, 'title': 'Greedy Algorithms, Dynamic Programming & Divide-and-Conquer', 'real_life_examples': [{'title': 'Real-Life Analogy: Cashier Change & Remembering Past Math Results', 'text': "• Greedy: Like a cashier giving you change using the fewest coins by always picking the largest coin denomination first (25c, then 10c, etc.).\n• Dynamic Programming: '1 + 1 + 1 + 1 = 4'. If I write another '+ 1', you instantly say '5' because you REMEMBERED the previous 4 without recalculating from scratch!"}], 'foundations': [{'number': '18.1', 'title': 'Greedy Method vs Dynamic Programming', 'content': "• <b>Greedy Method:</b> Makes locally optimal choice at each step hoping for global optimum. Never backtracks.<br/>&nbsp;&nbsp;- Examples: Fractional Knapsack, Huffman Coding, Kruskal's, Prim's, Dijkstra.<br/>• <b>Dynamic Programming (DP):</b> Solves subproblems once, stores results in a table (memoization/tabulation).<br/>&nbsp;&nbsp;- Requires <b>Optimal Substructure</b> AND <b>Overlapping Subproblems</b>.<br/>&nbsp;&nbsp;- Examples: 0/1 Knapsack, Longest Common Subsequence (LCS), Matrix Chain Multiplication, Floyd-Warshall.", 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: Fractional Knapsack is solved by Greedy (sort by value/weight in O(n log n)). 0/1 Knapsack CANNOT be solved by Greedy; it requires Dynamic Programming in O(n × W) pseudo-polynomial time!'}, {'number': '18.2', 'title': 'Longest Common Subsequence (LCS) Recurrence', 'content': '• For strings X of length m and Y of length n:<br/>&nbsp;&nbsp;• If <b>X[i] == Y[j]</b>: <b>LCS[i, j] = 1 + LCS[i - 1, j - 1]</b>.<br/>&nbsp;&nbsp;• If <b>X[i] ≠ Y[j]</b>: <b>LCS[i, j] = max(LCS[i - 1, j], LCS[i, j - 1])</b>.<br/>• <b>Time & Space:</b> O(m × n) time, reducible to O(min(m, n)) space using two rows.<br/>• <b>Matrix Chain Multiplication:</b> Cost recurrence: <b>m[i, j] = min_{i ≤ k < j} { m[i, k] + m[k+1, j] + p_{i-1}·p_k·p_j }</b>. Time: O(n³).', 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: In Matrix Chain Multiplication with n matrices, number of different parenthesizations is given by Catalan Number C_{n-1}!'}], 'worked_examples': [{'title': 'Worked Example: Huffman Code Tree Construction', 'problem': 'Given frequencies: a: 5, b: 9, c: 12, d: 13, e: 16, f: 45. Find the length of Huffman encoded string.', 'steps': ['Step 1: Pick two smallest: 5 and 9 ⇒ merge to node 14. Remaining: [c:12, d:13, (5+9):14, e:16, f:45].', 'Step 2: Pick two smallest: 12 and 13 ⇒ merge to node 25. Remaining: [14, e:16, 25, f:45].', 'Step 3: Pick two smallest: 14 and 16 ⇒ merge to node 30. Remaining: [25, 30, f:45].', 'Step 4: Pick two smallest: 25 and 30 ⇒ merge to node 55. Remaining: [f:45, 55].', 'Step 5: Merge 45 and 55 ⇒ root 100.', 'Step 6: Code lengths: f=1 bit, c=3, d=3, e=3, a=4, b=4. Weighted path length = (45×1) + (12×3) + (13×3) + (16×3) + (5×4) + (9×4) = 45 + 36 + 39 + 48 + 20 + 36 = 224 bits.'], 'answer': 'Total encoded length = 224 bits.'}], 'exam_traps': ['Huffman code is a prefix code: NO valid codeword is a prefix of any other codeword!', 'Huffman tree is always a strictly Full Binary Tree (every internal node has exactly 2 children).']}, ('ALGO', 3): {'sub_id': 'ALGO', 'chap_idx': 3, 'title': 'Graph Traversals, MST & Shortest Paths', 'real_life_examples': [{'title': 'Real-Life Analogy: GPS Navigation & Google Maps', 'text': "• Dijkstra's Algorithm: How Google Maps finds the quickest driving route to your destination without negative road tolls.\n• Minimum Spanning Tree: Laying down fiber-optic internet cables between cities with the absolute minimum total cable length while ensuring every city is connected."}], 'foundations': [{'number': '19.1', 'title': 'BFS vs DFS Comparison & Applications', 'content': "• <b>Breadth-First Search (BFS):</b> Uses a <b>Queue</b>. Time: <b>O(V + E)</b>.<br/>&nbsp;&nbsp;- Finds the <b>shortest path in unweighted graphs</b>.<br/>&nbsp;&nbsp;- Detects bipartiteness (2-coloring).<br/>• <b>Depth-First Search (DFS):</b> Uses a <b>Stack / Recursion</b>. Time: <b>O(V + E)</b>.<br/>&nbsp;&nbsp;- Detects cycles in directed graphs (via <b>Back Edges</b>).<br/>&nbsp;&nbsp;- Computes <b>Topological Sort</b> of a DAG (reverse of finish times).<br/>&nbsp;&nbsp;- Finds Strongly Connected Components (Kosaraju's / Tarjan's algorithm).", 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: In DFS of a directed graph, a cycle exists IF AND ONLY IF there is at least one BACK EDGE! Forward and Cross edges do NOT indicate a cycle.'}, {'number': '19.2', 'title': 'Dijkstra vs Bellman-Ford vs Floyd-Warshall', 'content': "• <b>Dijkstra's Algorithm:</b> Single-Source Shortest Path for <b>non-negative edge weights</b>.<br/>&nbsp;&nbsp;- Time: <b>O((V + E) log V)</b> using min-heap. FAILS for negative edge weights!<br/>• <b>Bellman-Ford Algorithm:</b> Works with <b>negative edge weights</b>.<br/>&nbsp;&nbsp;- Relaxes all edges (V - 1) times. Time: <b>O(V × E)</b>.<br/>&nbsp;&nbsp;- Detects negative-weight cycles (if distance decreases on V-th relaxation).<br/>• <b>Floyd-Warshall Algorithm:</b> All-Pairs Shortest Path in <b>O(V³)</b> time using dynamic programming.<br/>• <b>Kruskal vs Prim (MST):</b> Kruskal uses edges (O(E log E) with DSU); Prim grows from a vertex (O(E + V log V)).", 'crucial_rule': '🎯 GOLDEN RULE FOR GATE: If all edge weights in a graph are distinct, the Minimum Spanning Tree (MST) is 100% UNIQUE! Shortest path tree is NOT necessarily unique.'}], 'worked_examples': [{'title': "Worked Example: Kruskal's MST Edge Selection", 'problem': 'Given edges sorted by weight: (A-B, 1), (B-C, 2), (A-C, 2), (C-D, 3), (B-D, 4). Which edges are included in the MST?', 'steps': ['Step 1: Pick (A-B, 1) ⇒ No cycle, add to MST.', 'Step 2: Pick (B-C, 2) ⇒ No cycle, add to MST.', 'Step 3: Consider (A-C, 2) ⇒ A, B, C are already connected! Adding A-C creates cycle A-B-C-A. REJECT.', 'Step 4: Pick (C-D, 3) ⇒ No cycle, add to MST.', 'Step 5: We have 4 vertices and 3 edges (V - 1 = 3). MST is complete!'], 'answer': 'MST edges: (A-B, 1), (B-C, 2), (C-D, 3). Total weight = 6.'}], 'exam_traps': ["Dijkstra's algorithm can enter an infinite loop or give wrong answers if negative edge weights are present!", 'Topological sort exists IF AND ONLY IF the graph is a Directed Acyclic Graph (DAG).']}}
